scripts.build:
tsc -p tsconfig.json && node -e "const {cpSync, copyFileSync, writeFileSync} = require('node:fs'); cpSync('test/helpers', 'dist/test/helpers', { recursive: true }); copyFileSync('package.json', 'dist/package.json'); writeFileSync('dist/cli.js', '#!/usr/bin/env node
import { main, createProductionDependencies } from "./src/cli.js";
void main(process.argv.slice(2), createProductionDependencies()).then((code) => { process.exitCode = code; });
');"
